#!/usr/bin/env python3
"""Merge user data from three sources with differing schemas and priorities."""

import json

import numpy as np
import pandas as pd

JSON_PATH = "/data/source_a/users.json"
CSV_PATH = "/data/source_b/users.csv"
PARQUET_PATH = "/data/source_c/users.parquet"

OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

SOURCES = ["source_a", "source_b", "source_c"]
FIELDS = ["name", "email", "created_date", "status"]


def is_missing(value):
    if value is None:
        return True
    if isinstance(value, float) and np.isnan(value):
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def norm_str(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text or None


def norm_status(value):
    """Normalize string/boolean statuses to 'active' / 'inactive'."""
    if is_missing(value):
        return None
    if isinstance(value, (bool, np.bool_)):
        return "active" if value else "inactive"
    text = str(value).strip().lower()
    if text in ("true", "1", "yes", "active"):
        return "active"
    if text in ("false", "0", "no", "inactive"):
        return "inactive"
    return text or None


def norm_date(value):
    """Normalize any parseable date to YYYY-MM-DD."""
    if is_missing(value):
        return None
    ts = pd.to_datetime(value, errors="coerce")
    if pd.isna(ts):
        return norm_str(value)
    return ts.strftime("%Y-%m-%d")


def norm_user_id(value):
    if is_missing(value):
        return None
    return int(float(value))


def load_source_a():
    with open(JSON_PATH, "r", encoding="utf-8") as handle:
        records = json.load(handle)
    if isinstance(records, dict):  # tolerate {"users": [...]}
        records = next(v for v in records.values() if isinstance(v, list))
    out = {}
    for row in records:
        uid = norm_user_id(row.get("id", row.get("user_id")))
        if uid is None:
            continue
        out[uid] = {
            "name": norm_str(row.get("full_name", row.get("name"))),
            "email": norm_str(row.get("email", row.get("email_address"))),
            "created_date": norm_date(
                row.get("registration_date", row.get("created_at"))
            ),
            "status": norm_status(row.get("status")),
        }
    return out


def load_source_b():
    df = pd.read_csv(CSV_PATH)
    out = {}
    for _, row in df.iterrows():
        uid = norm_user_id(row.get("user_id", row.get("id")))
        if uid is None:
            continue
        out[uid] = {
            "name": norm_str(row.get("name", row.get("full_name"))),
            "email": norm_str(row.get("email_address", row.get("email"))),
            "created_date": norm_date(row.get("created_at", row.get("joined"))),
            "status": norm_status(row.get("is_active", row.get("status"))),
        }
    return out


def load_source_c():
    df = pd.read_parquet(PARQUET_PATH)
    out = {}
    for _, row in df.iterrows():
        uid = norm_user_id(row.get("userId", row.get("user_id")))
        if uid is None:
            continue
        out[uid] = {
            "name": norm_str(row.get("userName", row.get("full_name"))),
            "email": norm_str(row.get("email", row.get("email_address"))),
            "created_date": norm_date(row.get("joined", row.get("created_at"))),
            "status": norm_status(row.get("active", row.get("status"))),
        }
    return out


def main():
    data = {
        "source_a": load_source_a(),
        "source_b": load_source_b(),
        "source_c": load_source_c(),
    }

    user_ids = sorted({uid for source in data.values() for uid in source})

    merged_rows = []
    conflicts = []

    for uid in user_ids:
        merged = {"user_id": int(uid)}
        for field in FIELDS:
            present = {
                src: data[src][uid][field]
                for src in SOURCES
                if uid in data[src] and not is_missing(data[src][uid][field])
            }

            # Highest-priority source that actually has a value wins.
            selected = None
            for src in SOURCES:
                if src in present:
                    selected = present[src]
                    break

            merged[field] = selected

            if len(set(present.values())) > 1:
                conflicts.append(
                    {
                        "user_id": int(uid),
                        "field": field,
                        "values": present,
                        "selected": selected,
                    }
                )

        merged_rows.append(merged)

    out_df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email",
                                                 "created_date", "status"])
    out_df["user_id"] = out_df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        out_df[col] = out_df[col].astype("string")

    out_df.to_parquet(OUT_PARQUET, index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2)
        handle.write("\n")

    print(f"Wrote {len(out_df)} users to {OUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUT_CONFLICTS}")


if __name__ == "__main__":
    main()
